function checkDepositedAfterBankSnapshot(c,bankObj){if(!c||!['הופקד - במעקב','נפרע'].includes(c.status))return false;const depositSeq=Number(c.depositSeq),snapshotSeq=Number(bankObj?.snapshotSeq);if(Number.isSafeInteger(depositSeq)&&depositSeq>0&&Number.isSafeInteger(snapshotSeq)&&snapshotSeq>0)return depositSeq>snapshotSeq;const asOf=bankObj?.asOfDate||(bankObj?.updatedAt?String(bankObj.updatedAt).slice(0,10):'');if(c.depositedAt&&bankObj?.updatedAt){const a=Date.parse(c.depositedAt),b=Date.parse(bankObj.updatedAt);if(Number.isFinite(a)&&Number.isFinite(b))return a>b}return !!(c.depositDate&&asOf&&c.depositDate>asOf)}
