function triStatusClass(value){return value===true?'tri-status-yes':value===false?'tri-status-no':''}
function inlineTri(t,field,label){const v=t[field];return `<div class="status-toggle" title="${esc(label)} · לחיצה חוזרת על הבחירה מבטלת אותה"><button class="yes ${v===true?'active':''}" onclick="setInlineTri('${esc(t.id)}','${field}',true);event.stopPropagation()">כן</button><button class="no ${v===false?'active':''}" onclick="setInlineTri('${esc(t.id)}','${field}',false);event.stopPropagation()">לא</button></div>`}
function inlineBool(t,field,label){const v=!!t[field];return `<div class="status-toggle binary" title="${esc(label)}"><button class="yes ${v?'active':''}" onclick="setInlineBool('${esc(t.id)}','${field}',true);event.stopPropagation()">כן</button><button class="no ${!v?'active':''}" onclick="setInlineBool('${esc(t.id)}','${field}',false);event.stopPropagation()">לא</button></div>`}
function setInlineTri(id,field,value){const t=state.transactions.find(x=>x.id===id);if(!t||!['invoiceReceived','signed','supplied'].includes(field))return;t[field]=t[field]===value?null:value;t.updatedAt=new Date().toISOString();scheduleSave('הסטטוס עודכן');renderSupplier({scrollMode:'preserve'})}
function setInlineBool(id,field,value){const t=state.transactions.find(x=>x.id===id);if(!t||field!=='hmIssued')return;if(t[field]===value)return;t[field]=value;t.updatedAt=new Date().toISOString();scheduleSave('הסטטוס עודכן');renderSupplier({scrollMode:'preserve'})}
function saveInlineText(id,field,el){const t=state.transactions.find(x=>x.id===id);if(!t||!['supplyInfo','note'].includes(field))return;const value=el.value.trim();if((t[field]||'')===value)return;t[field]=value;t.updatedAt=new Date().toISOString();scheduleSave(field==='supplyInfo'?'פרטי האספקה עודכנו':'ההערה עודכנה')}
function txRow(t,balance,assignedYear=null){const invoiceStatus=triStatusClass(t.invoiceReceived),signedStatus=triStatusClass(t.signed),suppliedStatus=triStatusClass(t.supplied),boundaryYear=validSupplierYear(t.yearEnd),carry=supplierYearView==='current'&&assignedYear!==null,yearTag=carry?`<span class="year-tag carry">פתוח מ־${esc(assignedYear)}</span>`:boundaryYear!==null?`<span class="year-tag">סוף ${esc(boundaryYear)}</span>`:'';return `<tr class="${t.supplied===false?'pending':''} ${supplierBulkSelected.has(t.id)?'bulk-selected-row':''} ${supplierMoveTargetId===t.id?'supplier-move-source-row':''} ${carry?'year-carry-row':''} ${boundaryYear!==null?'year-boundary-row':''}" data-tx-id="${esc(t.id)}" data-search="${esc(`${t.action||''} ${t.note||''} ${t.supplyInfo||''} ${t.source?.row||''} ${assignedYear||''}`)}">${supplierBulkMode?`<td class="bulk-check-col"><input class="bulk-check" type="checkbox" ${supplierBulkSelected.has(t.id)?'checked':''} aria-label="בחר תנועה ${esc(t.sequence)}" onchange="toggleSupplierBulkRow('${esc(t.id)}',this.checked)"></td>`:''}<td class="col-seq" title="${t.source?.sheet?`${esc(t.source.sheet)}${t.source?.row?` · שורת מקור ${esc(t.source.row)}`:''}`:''}">${esc(t.sequence)}</td><td class="col-invoice ${invoiceStatus}">${inlineTri(t,'invoiceReceived','חשבונית התקבלה')}</td><td class="col-action"><div class="action-text">${esc(t.action||'')}${yearTag}</div>${t.correction?'<div class="badge red correction-badge">תיקון ייבוא</div>':''}</td><td class="money col-money badtext">${t.debit?`<b>${money(t.debit)}</b>`:''}</td><td class="money col-money goodtext">${t.credit?`<b>${money(t.credit)}</b>`:''}</td><td class="money col-balance ${balance<0?'badtext':'goodtext'}"><b>${money(balance)}</b></td><td class="col-status ${signedStatus}">${inlineTri(t,'signed','חתום')}</td><td class="col-status ${suppliedStatus}">${inlineTri(t,'supplied','סופק')}</td><td class="col-supply"><input class="inline-input" value="${esc(t.supplyInfo||'')}" placeholder="תאריך / פרטי אספקה" onkeydown="if(event.key==='Enter'){this.blur()}" onblur="saveInlineText('${esc(t.id)}','supplyInfo',this)"></td><td class="col-status">${inlineBool(t,'hmIssued','ח״מ יצא')}</td><td class="col-note"><input class="inline-input" value="${esc(t.note||'')}" placeholder="הערה" onkeydown="if(event.key==='Enter'){this.blur()}" onblur="saveInlineText('${esc(t.id)}','note',this)"></td><td class="col-row-actions"><div class="row-actions"><button class="icon-btn add-row" title="הוסף תנועה מתחת לשורה זו" onclick="openTransactionModal(null,'${esc(t.supplierId)}','${esc(t.id)}')">＋</button><button class="icon-btn" title="עריכת כל פרטי התנועה" onclick="openTransactionModal('${esc(t.id)}')">✎</button></div></td></tr>`}
function modal(title,body,foot=''){const back=$('#modalBackdrop');$('#modal').innerHTML=`<div class="modal-head"><h3>${title}</h3><button class="icon-btn" onclick="closeModal()">✕</button></div><div class="modal-body">${body}</div><div class="modal-foot">${foot}</div>`;back.classList.add('open')}
function closeModal(){$('#modalBackdrop').classList.remove('open')}
$('#modalBackdrop').addEventListener('click',e=>{if(e.target.id==='modalBackdrop')closeModal()});
function triSelect(id,label,val,na=true){return `<div class="field"><label>${label}</label><select id="${id}">${na?`<option value="null" ${val==null?'selected':''}>לא רלוונטי</option>`:''}<option value="true" ${val===true?'selected':''}>כן</option><option value="false" ${val===false?'selected':''}>לא</option></select></div>`}
function parseTri(id){const v=$('#'+id).value;return v==='true'?true:v==='false'?false:null}
function openTransactionModal(id=null,supplierId=null,insertAfterId=null){
  const t=id?state.transactions.find(x=>x.id===id):null;
  const anchor=insertAfterId?state.transactions.find(x=>x.id===insertAfterId):null;
  const sid=t?.supplierId||anchor?.supplierId||supplierId||currentSupplierId||state.suppliers[0]?.id||'';
  const opts=state.suppliers.map(s=>`<option value="${esc(s.id)}" ${s.id===sid?'selected':''}>${esc(s.name)}</option>`).join('');
  const positionNotice=!t&&anchor?`<div class="field full"><div class="notice">התנועה תתווסף <b>מיד אחרי שורה ${esc(anchor.sequence)}</b>. שאר השורות ימוספרו מחדש אוטומטית, והיתרות יחושבו מחדש.</div></div>`:'',yearNotice=t&&validSupplierYear(t.yearEnd)!==null?`<div class="field full"><div class="notice">שורה זו מסומנת כ<b>סוף שנה ${esc(t.yearEnd)}</b>. כדי להעביר אותה לספק אחר יש להסיר קודם את סימון סוף השנה דרך מצב “בחירה”.</div></div>`:'';
  modal(t?'עריכת תנועה':anchor?'הוספת תנועה באמצע הכרטיס':'תנועה חדשה',`<div class="form-grid"><div class="field full"><label>ספק</label><select id="fSupplier" ${anchor||validSupplierYear(t?.yearEnd)!==null?'disabled':''}>${opts}</select></div>${positionNotice}${yearNotice}<div class="field full"><label>פעולה</label><input id="fAction" value="${esc(t?.action||'')}" placeholder="לדוגמה: הזמנה 1234 / תשלום"></div><div class="field"><label>סכום חובה</label><input id="fDebit" class="number-input" type="number" step="1" value="${Number(t?.debit||0)||''}"></div><div class="field"><label>סכום זכות</label><input id="fCredit" class="number-input" type="number" step="1" value="${Number(t?.credit||0)||''}"></div>${triSelect('fInvoice','חשבונית התקבלה',t?.invoiceReceived??false,true)}${triSelect('fSigned','חתום',t?.signed??false,true)}${triSelect('fSupplied','סופק',t?.supplied??false,true)}<div class="field"><label>זמן / פרטי אספקה</label><input id="fSupplyInfo" value="${esc(t?.supplyInfo||'')}" placeholder="תאריך, שבוע, הערה…"></div><div class="field"><label>ח״מ יצא</label><select id="fHm"><option value="false" ${!t?.hmIssued?'selected':''}>לא</option><option value="true" ${t?.hmIssued?'selected':''}>כן</option></select></div><div class="field full"><label>הערה</label><textarea id="fNote">${esc(t?.note||'')}</textarea></div>${t?.source?`<div class="field full"><div class="notice">מקור: ${esc(t.source.sheet)} · שורה ${esc(t.source.row)}. עריכה כאן אינה משנה את קובץ האקסל המקורי.</div></div>`:''}</div>`,`<button class="btn primary" onclick="saveTransaction('${id||''}','${insertAfterId||''}')">שמור</button>${t?`<button class="btn danger" onclick="deleteTransaction('${esc(t.id)}')">מחק תנועה</button>`:''}<button class="btn" onclick="closeModal()">ביטול</button>`)
}
function saveTransaction(id,insertAfterId=''){
  const existing=id?state.transactions.find(x=>x.id===id):null;
  const oldSupplierId=existing?.supplierId||null;
  const supplierId=$('#fSupplier').value,action=$('#fAction').value.trim(),debit=Math.max(0,Number($('#fDebit').value||0)),credit=Math.max(0,Number($('#fCredit').value||0));
  if(!supplierId)return toast('יש לבחור ספק');
  if(!action&&!debit&&!credit)return toast('יש להזין פעולה או סכום');
  if(debit&&credit&&!confirm('הוזנו גם חובה וגם זכות באותה תנועה. לשמור כך?'))return;
  const row={...(existing||{}),id:existing?.id||uid(),supplierId,sequence:existing?.sequence||0,kind:debit?'חיוב':credit?'זיכוי/תשלום':'הערה',action,debit,credit,invoiceReceived:parseTri('fInvoice'),signed:parseTri('fSigned'),supplied:parseTri('fSupplied'),supplyInfo:$('#fSupplyInfo').value.trim(),hmIssued:$('#fHm').value==='true',note:$('#fNote').value.trim(),updatedAt:new Date().toISOString()};
  if(existing){
    Object.assign(existing,row);
    if(oldSupplierId!==supplierId){resequenceSupplier(oldSupplierId);insertTransactionAfter(existing,supplierId,null)}
  }else{
    state.transactions.push(row);
    insertTransactionAfter(row,supplierId,insertAfterId||null)
  }
  currentSupplierId=supplierId;closeModal();scheduleSave(existing?'התנועה עודכנה':insertAfterId?'התנועה נוספה במיקום שבחרת':'התנועה נוספה');if(currentView==='supplier')renderSupplier({scrollMode:(!existing&&!insertAfterId)?'end':'preserve'});else render()
}
function deleteTransaction(id){const t=state.transactions.find(x=>x.id===id);if(!t)return;if(validSupplierYear(t.yearEnd)!==null)return toast(`יש להסיר קודם את סימון סוף שנה ${t.yearEnd} מהשורה`);if(!confirm('למחוק את התנועה? היתרות יחושבו מחדש אוטומטית.'))return;const sid=t.supplierId;state.transactions=state.transactions.filter(x=>x.id!==id);resequenceSupplier(sid);closeModal();scheduleSave('התנועה נמחקה');if(currentView==='supplier')renderSupplier({scrollMode:'preserve'});else render()}
function openSelectedSupplierEditor(){const id=$('#settingsSupplierEdit')?.value;if(!id)return toast('יש לבחור ספק לעריכה');openSupplierModal(id)}
function openSupplierModal(id=null){const s=id?state.suppliers.find(x=>x.id===id):null;modal(s?'עריכת ספק':'ספק חדש',`<div class="form-grid"><div class="field full"><label>שם ספק</label><input id="sName" value="${esc(s?.name||'')}"></div><div class="field full"><label>הערה</label><input id="sNote" value="${esc(s?.note||'')}"></div></div>`,`<button class="btn primary" onclick="saveSupplier('${id||''}')">שמור</button><button class="btn" onclick="closeModal()">ביטול</button>`)}
function saveSupplier(id){const name=$('#sName').value.trim();if(!name)return toast('יש להזין שם ספק');let s=id?state.suppliers.find(x=>x.id===id):null;if(s){s.name=name;s.note=$('#sNote').value.trim()}else{const nextOrder=state.suppliers.reduce((m,x)=>Math.max(m,supplierSortValue(x)),-1)+1;s={id:uid('SUP'),name,note:$('#sNote').value.trim(),active:true,sortOrder:nextOrder};state.suppliers.push(s);currentSupplierId=s.id}closeModal();scheduleSave(s?'הספק נשמר':'הספק נוסף');render()}
function customerDebtStatus(d){if(d.paid&&d.invoiceIssued)return{key:'closed',text:'נסגר',cls:'green'};if(d.paid&&!d.invoiceIssued)return{key:'invoice',text:'שולם · חסרה חשבונית',cls:'red'};if(!d.paid&&d.invoiceIssued)return{key:'open',text:'חשבונית יצאה · טרם שולם',cls:'yellow'};return{key:'open',text:'חוב פתוח',cls:'yellow'}}
function customerStats(){const rows=state.customerDebts||[];return{openTotal:rows.filter(d=>!d.paid).reduce((s,d)=>s+Number(d.amount||0),0),allTotal:rows.reduce((s,d)=>s+Number(d.amount||0),0),open:rows.filter(d=>!d.paid).length,missingInvoice:rows.filter(d=>d.paid&&!d.invoiceIssued).length,closed:rows.filter(d=>d.paid&&d.invoiceIssued).length,trackedOrders:(state.customerOrders||[]).length}}
function setCustomerTab(tab){if(!['debts','orders'].includes(tab)||tab===customerTab)return;customerTab=tab;customerBulkSelected.clear();renderCustomers()}
function customerBulkSource(){return customerTab==='debts'?(state.customerDebts||[]):(state.customerOrders||[])}
function customerVisibleBulkIds(){return [...document.querySelectorAll('[data-customer-bulk-id]')].map(el=>el.dataset.customerBulkId).filter(Boolean)}
function toggleCustomerBulkMode(){customerBulkMode=!customerBulkMode;customerBulkSelected.clear();renderCustomers()}
function toggleCustomerBulkRow(id,checked){if(!customerBulkMode)return;if(!customerBulkSource().some(x=>x.id===id))return;if(checked)customerBulkSelected.add(id);else customerBulkSelected.delete(id);syncCustomerBulkUi()}
function toggleCustomerBulkVisible(checked){if(!customerBulkMode)return;customerVisibleBulkIds().forEach(id=>checked?customerBulkSelected.add(id):customerBulkSelected.delete(id));document.querySelectorAll('[data-customer-bulk-check]').forEach(cb=>cb.checked=checked);syncCustomerBulkUi()}
function customerBulkHeader(){return customerBulkMode?'<th class="bulk-check-col"><input id="customerBulkAll" class="bulk-check" type="checkbox" title="בחר את כל השורות המוצגות" onchange="toggleCustomerBulkVisible(this.checked)"></th>':''}
function customerBulkCell(id){return customerBulkMode?`<td class="bulk-check-col"><input class="bulk-check" data-customer-bulk-check type="checkbox" ${customerBulkSelected.has(id)?'checked':''} aria-label="בחר שורה" onchange="toggleCustomerBulkRow('${esc(id)}',this.checked)"></td>`:''}
function customerBulkControls(){return `<div class="module-bulk-controls"><button class="btn small bulk-select-toggle ${customerBulkMode?'active':''}" onclick="toggleCustomerBulkMode()">${customerBulkMode?'סיום בחירה':'בחירה'}</button>${customerBulkMode?`<button id="customerBulkDelete" class="btn danger small bulk-delete-btn" onclick="deleteSelectedCustomerRows()" disabled>מחק נבחרים</button>`:''}</div>`}
function syncCustomerBulkUi(){if(!customerBulkMode)return;const valid=new Set(customerBulkSource().map(x=>x.id));[...customerBulkSelected].forEach(id=>{if(!valid.has(id))customerBulkSelected.delete(id)});const del=$('#customerBulkDelete');if(del){del.disabled=!customerBulkSelected.size;del.textContent=customerBulkSelected.size?`מחק ${customerBulkSelected.size}`:'מחק נבחרים'}const visible=customerVisibleBulkIds(),selectedVisible=visible.filter(id=>customerBulkSelected.has(id)).length,all=$('#customerBulkAll');if(all){all.checked=visible.length>0&&selectedVisible===visible.length;all.indeterminate=selectedVisible>0&&selectedVisible<visible.length}document.querySelectorAll('[data-customer-bulk-id]').forEach(row=>row.classList.toggle('bulk-selected-row',customerBulkSelected.has(row.dataset.customerBulkId)))}
function deleteSelectedCustomerRows(){const source=customerBulkSource(),valid=new Set(source.map(x=>x.id)),ids=[...customerBulkSelected].filter(id=>valid.has(id));if(!ids.length)return toast('לא נבחרו שורות למחיקה');const label=customerTab==='debts'?'חובות לקוחות':'רשומות מעקב הזמנות';if(!confirm(`למחוק ${ids.length} ${label} שנבחרו?\n\nהמחיקה תישמר בגיבוי ובסנכרון כמו כל שינוי אחר.`))return;const set=new Set(ids);if(customerTab==='debts')state.customerDebts=state.customerDebts.filter(x=>!set.has(x.id));else state.customerOrders=state.customerOrders.filter(x=>!set.has(x.id));customerBulkSelected.clear();scheduleSave(`${ids.length} ${label} נמחקו`);renderCustomers()}
function customerBottomSummary(st){
  const sourceNote=customerTab==='orders'?`<div class="customer-summary-note">סימוני V / VV / VVV נשמרים כפי שהתקבלו, בלי להמציא להם משמעות עסקית שלא הוגדרה.</div>`:'';
  return `<section class="customer-bottom-summary"><div class="customer-bottom-head"><div><h2>סיכום לקוחות</h2><p>סיכום הנתונים מופיע בסוף אזור הטבלה ונגלל יחד איתו.</p></div></div><div class="customer-bottom-grid"><div><span>חוב פתוח</span><b class="badtext">${money(st.openTotal)}</b><small>${st.open} לקוחות</small></div><div><span>שולם · חסרה חשבונית</span><b class="warntext">${st.missingInvoice}</b><small>חשבונית עדיין לא נסגרה</small></div><div><span>נסגרו</span><b class="goodtext">${st.closed}</b><small>תשלום + חשבונית</small></div><div><span>מעקב הזמנות</span><b>${st.trackedOrders}</b><small>רשומות במעקב</small></div></div>${sourceNote}</section>`;
}
function renderCustomers({resultsOnly=false}={}){
  const st=customerStats(),q=(customerSearch||'').trim(),summary=customerBottomSummary(st);
  let table='';
  if(customerTab==='debts'){
    const rows=(state.customerDebts||[]).filter(d=>{
      const ds=customerDebtStatus(d);
      if(customerFilter==='all'&&ds.key==='closed')return false;
      if(customerFilter==='open'&&d.paid)return false;
      if(customerFilter==='invoice'&&!(d.paid&&!d.invoiceIssued))return false;
      if(customerFilter==='closed'&&ds.key!=='closed')return false;
      if(q&&!`${d.customerName||''} ${d.orderNumber||''} ${d.phone||''} ${d.note||''}`.includes(q))return false;
      return true;
    }).sort((a,b)=>Number(b.amount||0)-Number(a.amount||0));
    table=`<table class="customer-table ${customerBulkMode?'customer-bulk-table':''}"><thead><tr>${customerBulkHeader()}<th>לקוח</th><th>סכום</th><th>הזמנה</th><th>שולם</th><th>חשבונית יצאה</th><th>מצב</th><th>הערה</th><th></th></tr></thead><tbody>${rows.map(debtRow).join('')||`<tr><td colspan="${customerBulkMode?9:8}" class="empty">אין חובות המתאימים לסינון.</td></tr>`}</tbody></table>`;
  }else{
    const rows=(state.customerOrders||[]).filter(o=>{
      if(customerOrderFilter==='mattress'&&!o.mattressMarked)return false;
      if(customerOrderFilter==='attention'&&!o.sourceAttention)return false;
      if(q&&!`${o.orderNumber||''} ${o.customerName||''} ${o.sourceMarkA||''} ${o.sourceMarkB||''} ${o.mattressRaw||''} ${o.note||''}`.includes(q))return false;
      return true;
    }).sort((a,b)=>String(a.orderNumber||'').localeCompare(String(b.orderNumber||''),'he',{numeric:true}));
    table=`<table class="customer-orders-table ${customerBulkMode?'customer-bulk-table':''}"><thead><tr>${customerBulkHeader()}<th>הזמנה</th><th>לקוח</th><th>סימון 1</th><th>סימון 2</th><th>מזרונים</th><th>הערה</th></tr></thead><tbody>${rows.map(customerOrderRow).join('')||`<tr><td colspan="${customerBulkMode?7:6}" class="empty">אין הזמנות המתאימות לסינון.</td></tr>`}</tbody></table>`;
  }
  const body=`<div class="panel customer-work-panel"><div class="table-wrap module-table customer-work-table">${table}${summary}</div></div>`;
  if(resultsOnly){
    const host=$('#customerSearchResults');
    if(host)host.innerHTML=body;
    bindScrollViewport(`customers:${customerTab}`,$('.customer-work-table'));
    syncCustomerBulkUi();
    return;
  }
  const filters=customerTab==='debts'?`<div class="filters"><button class="chip-filter ${customerFilter==='all'?'active':''}" onclick="customerFilter='all';renderCustomers()">הכל</button><button class="chip-filter ${customerFilter==='open'?'active':''}" onclick="customerFilter='open';renderCustomers()">חוב פתוח</button><button class="chip-filter ${customerFilter==='invoice'?'active':''}" onclick="customerFilter='invoice';renderCustomers()">שולם בלי חשבונית</button><button class="chip-filter ${customerFilter==='closed'?'active':''}" onclick="customerFilter='closed';renderCustomers()">נסגר</button></div>`:`<div class="filters"><button class="chip-filter ${customerOrderFilter==='all'?'active':''}" onclick="customerOrderFilter='all';renderCustomers()">הכל</button><button class="chip-filter ${customerOrderFilter==='mattress'?'active':''}" onclick="customerOrderFilter='mattress';renderCustomers()">מזרונים</button><button class="chip-filter ${customerOrderFilter==='attention'?'active':''}" onclick="customerOrderFilter='attention';renderCustomers()">דורש תשומת לב</button></div>`;
  $('#main').innerHTML=`<div class="customers-view"><div class="module-toolbar customer-command"><div class="module-tabs"><button class="chip-filter ${customerTab==='debts'?'active':''}" onclick="setCustomerTab('debts')">חובות</button><button class="chip-filter ${customerTab==='orders'?'active':''}" onclick="setCustomerTab('orders')">מעקב הזמנות</button></div>${customerBulkControls()}<input class="customer-search" placeholder="${customerTab==='debts'?'חיפוש לקוח, הזמנה, טלפון או הערה…':'חיפוש הזמנה, לקוח או סימון…'}" value="${esc(customerSearch)}" oninput="customerSearch=this.value;renderCustomers({resultsOnly:true})">${filters}${customerTab==='debts'?'<button class="btn primary small customer-add-btn" onclick="openDebtModal()">+ חוב לקוח</button>':''}</div><div id="customerSearchResults">${body}</div></div>`;
  mountViewLayout({sourceSelector:'.customers-view',headCount:1,className:'customers-view'});
  bindScrollViewport(`customers:${customerTab}`,$('.customer-work-table'));
  syncCustomerBulkUi();
}
