function openDebtModal(id=null){const d=id?state.customerDebts.find(x=>x.id===id):null;modal(d?'עריכת חוב לקוח':'חוב לקוח חדש',`<div class="form-grid"><div class="field"><label>שם לקוח</label><input id="dName" value="${esc(d?.customerName||'')}"></div><div class="field"><label>סכום חוב</label><input id="dAmount" class="number-input" type="number" step="1" min="0" value="${Number(d?.amount||0)||''}"></div><div class="field"><label>מספר הזמנה</label><input id="dOrder" value="${esc(d?.orderNumber||'')}"></div><div class="field"><label>טלפון</label><input id="dPhone" value="${esc(d?.phone||'')}"></div><div class="field"><label>שולם</label><select id="dPaid"><option value="false" ${!d?.paid?'selected':''}>לא</option><option value="true" ${d?.paid?'selected':''}>כן</option></select></div><div class="field"><label>חשבונית יצאה</label><select id="dInvoice"><option value="false" ${!d?.invoiceIssued?'selected':''}>לא</option><option value="true" ${d?.invoiceIssued?'selected':''}>כן</option></select></div><div class="field full"><label>הערה</label><textarea id="dNote">${esc(d?.note||'')}</textarea></div></div>`,`<button class="btn primary" onclick="saveDebt('${id||''}')">שמור</button>${d?`<button class="btn danger" onclick="deleteDebt('${esc(d.id)}')">מחק</button>`:''}<button class="btn" onclick="closeModal()">ביטול</button>`)}
function saveDebt(id=''){const name=$('#dName').value.trim(),amount=Math.max(0,Number($('#dAmount').value||0));if(!name)return toast('יש להזין שם לקוח');if(!amount)return toast('יש להזין סכום חוב');let d=id?state.customerDebts.find(x=>x.id===id):null;const paid=$('#dPaid').value==='true',invoiceIssued=$('#dInvoice').value==='true',now=new Date().toISOString();const row={...(d||{}),id:d?.id||uid('DEBT'),customerName:name,amount,orderNumber:$('#dOrder').value.trim(),phone:$('#dPhone').value.trim(),paid,invoiceIssued,note:$('#dNote').value.trim(),updatedAt:now,paidAt:paid?(d?.paidAt||now):null,invoiceIssuedAt:invoiceIssued?(d?.invoiceIssuedAt||now):null,closedAt:paid&&invoiceIssued?(d?.closedAt||now):null};if(d)Object.assign(d,row);else state.customerDebts.push(row);closeModal();scheduleSave(d?'חוב הלקוח עודכן':'חוב הלקוח נוסף');renderCustomers()}
