function serviceStatus(c){if(c.closed)return{key:'closed',text:'נסגר',cls:'green'};if(c.escalated)return{key:'escalated',text:'הוקפץ',cls:'red'};if(c.sent)return{key:'sent',text:'נשלח',cls:'green'};if(c.followUp)return{key:'follow',text:'במעקב',cls:'yellow'};return{key:'open',text:'פתוח',cls:'yellow'}}
function serviceVisibleBulkIds(){return [...document.querySelectorAll('[data-service-bulk-id]')].map(el=>el.dataset.serviceBulkId).filter(Boolean)}
function toggleServiceBulkMode(){serviceBulkMode=!serviceBulkMode;serviceBulkSelected.clear();renderService()}
function toggleServiceBulkRow(id,checked){if(!serviceBulkMode||!state.serviceCalls.some(x=>x.id===id))return;if(checked)serviceBulkSelected.add(id);else serviceBulkSelected.delete(id);syncServiceBulkUi()}
function toggleServiceBulkVisible(){if(!serviceBulkMode)return;const ids=serviceVisibleBulkIds(),allSelected=ids.length>0&&ids.every(id=>serviceBulkSelected.has(id));ids.forEach(id=>allSelected?serviceBulkSelected.delete(id):serviceBulkSelected.add(id));syncServiceBulkUi()}
function serviceBulkControls(){return `<div class="module-bulk-controls"><button class="btn small bulk-select-toggle ${serviceBulkMode?'active':''}" onclick="toggleServiceBulkMode()">${serviceBulkMode?'סיום בחירה':'בחירה'}</button>${serviceBulkMode?`<button id="serviceBulkAll" class="btn small bulk-select-all-btn" onclick="toggleServiceBulkVisible()">בחר הכל</button><button id="serviceBulkDelete" class="btn danger small bulk-delete-btn" onclick="deleteSelectedServiceCalls()" disabled>מחק נבחרים</button>`:''}</div>`}
function syncServiceBulkUi(){if(!serviceBulkMode)return;const valid=new Set(state.serviceCalls.map(x=>x.id));[...serviceBulkSelected].forEach(id=>{if(!valid.has(id))serviceBulkSelected.delete(id)});const del=$('#serviceBulkDelete');if(del){del.disabled=!serviceBulkSelected.size;del.textContent=serviceBulkSelected.size?`מחק ${serviceBulkSelected.size}`:'מחק נבחרים'}const visible=serviceVisibleBulkIds(),all=visible.length>0&&visible.every(id=>serviceBulkSelected.has(id)),allBtn=$('#serviceBulkAll');if(allBtn)allBtn.textContent=all?'בטל הכל':'בחר הכל';document.querySelectorAll('[data-service-bulk-id]').forEach(card=>{const selected=serviceBulkSelected.has(card.dataset.serviceBulkId);card.classList.toggle('bulk-selected-card',selected);const cb=card.querySelector('[data-service-bulk-check]');if(cb)cb.checked=selected})}
function deleteSelectedServiceCalls(){const valid=new Set(state.serviceCalls.map(x=>x.id)),ids=[...serviceBulkSelected].filter(id=>valid.has(id));if(!ids.length)return toast('לא נבחרו קריאות שירות למחיקה');if(!confirm(`למחוק ${ids.length} קריאות שירות שנבחרו?\n\nהפעולה מוחקת את הקריאות עצמן, כפי שעושה כפתור המחיקה בעריכת קריאה.`))return;const set=new Set(ids);state.serviceCalls=state.serviceCalls.filter(x=>!set.has(x.id));serviceBulkSelected.clear();scheduleSave(`${ids.length} קריאות שירות נמחקו`);renderService()}
function renderService({resultsOnly=false}={}){const q=(serviceSearch||'').trim();let rows=(state.serviceCalls||[]).filter(c=>{const st=serviceStatus(c);if(serviceFilter==='all'&&c.closed)return false;if(serviceFilter==='open'&&st.key!=='open')return false;if(serviceFilter==='follow'&&(!c.followUp||c.closed))return false;if(serviceFilter==='escalated'&&(!c.escalated||c.closed))return false;if(serviceFilter==='closed'&&!c.closed)return false;if(q&&!`${c.customerName||''} ${c.orderNumber||''} ${c.phone||''} ${c.address||''} ${c.description||''} ${c.note||''}`.includes(q))return false;return true}).sort((a,b)=>String(b.openedAt||'').localeCompare(String(a.openedAt||'')));const open=state.serviceCalls.filter(c=>!c.closed).length,follow=state.serviceCalls.filter(c=>c.followUp&&!c.closed).length,escalated=state.serviceCalls.filter(c=>c.escalated&&!c.closed).length,closed=state.serviceCalls.filter(c=>c.closed).length;const grid=rows.map(serviceCard).join('')||'<div class="empty module-empty">אין קריאות המתאימות לסינון.</div>';if(resultsOnly){const host=$('#serviceSearchResults');if(host)host.innerHTML=grid;syncServiceBulkUi();return}$('#main').innerHTML=`<section class="hero"><div><h1>קריאות שירות</h1><p>כל קריאה נשארת בתהליך ברור: פתוח → מעקב → נשלח / הוקפץ → נסגר.</p></div><div class="actions"><button class="btn primary" onclick="openServiceModal()">+ פתיחת קריאה</button></div></section><div class="module-toolbar service-toolbar"><input class="service-search" placeholder="חיפוש לקוח, הזמנה, טלפון או תוכן הקריאה…" value="${esc(serviceSearch)}" oninput="serviceSearch=this.value;renderService({resultsOnly:true})"><div class="filters"><button class="chip-filter ${serviceFilter==='all'?'active':''}" onclick="serviceFilter='all';renderService()">הכל</button><button class="chip-filter ${serviceFilter==='open'?'active':''}" onclick="serviceFilter='open';renderService()">פתוחות</button><button class="chip-filter ${serviceFilter==='follow'?'active':''}" onclick="serviceFilter='follow';renderService()">מעקב</button><button class="chip-filter ${serviceFilter==='escalated'?'active':''}" onclick="serviceFilter='escalated';renderService()">הקפצה</button><button class="chip-filter ${serviceFilter==='closed'?'active':''}" onclick="serviceFilter='closed';renderService()">נסגרו</button></div>${serviceBulkControls()}</div><div id="serviceSearchResults" class="service-grid ${serviceBulkMode?'bulk-card-mode':''}">${grid}</div><section class="module-bottom-summary"><div class="kpis module-kpis"><div class="kpi"><div class="label">פתוחות</div><div class="value badtext">${open}</div></div><div class="kpi"><div class="label">במעקב</div><div class="value warntext">${follow}</div></div><div class="kpi"><div class="label">הוקפצו</div><div class="value badtext">${escalated}</div></div><div class="kpi"><div class="label">נסגרו</div><div class="value goodtext">${closed}</div></div></div></section>`;mountViewLayout({headCount:2,className:'service-view-shell',scrollKey:`service:${serviceFilter}`});syncServiceBulkUi()}
