async function refreshKupaReadout({force=false}={}){if(!loadSession()||!navigator.onLine)return false;try{if(!force){const meta=await readKupaReadOnlyMeta();if(!meta)return false;const rev=Number(meta.revision||0);if(rev>0&&rev<=kupaReadRevision){recomputeKupaNetFromCache();return true}}const row=await readKupaReadOnlyCloud();if(!row)return false;kupaReadRevision=Number(row.revision||0);rememberKupaNetState(row.state||{});return true}catch(e){console.error('kupa read-only refresh',e);return false}}
async function rpcSaveSharedChecks(checks,expectedRevision){const payload={version:1,checks:normalizeSharedChecks(checks)},expected=Number(expectedRevision||0);if(!Number.isSafeInteger(expected)||expected<0)throw new Error('Revision הצ\'קים המקומי אינו תקין');const r=await supaFetch(`/rest/v1/rpc/${SHARED_CHECKS_RPC}`,{method:'POST',body:JSON.stringify({p_document_name:SHARED_CHECKS_DOC,p_expected_revision:expected,p_state:payload})});const txt=await r.text();let j;try{j=txt?JSON.parse(txt):null}catch(e){j=null}return {r,j,txt,row:Array.isArray(j)?j[0]:j}}
function mergeSharedChecks(base,local,remote){const conflicts=[];const checks=mergeArray(base||[],local||[],remote||[],'id',conflicts,'check');return {checks:normalizeSharedChecks(checks),conflicts}}
async function syncSharedChecksFromCloud({quiet=false,required=false}={}){if(!loadSession()||checksCloudBusy||!navigator.onLine)return false;checksCloudBusy=true;try{const row=await readSharedChecksCloud();if(!row){checksCloudLastError='לא נמצא מסמך צ\'קים משותף בענן';if(required)throw new Error('מאגר הצ\'קים המשותף חסר. יש להריץ את מיגרציית ה-cutover לפני העלאת הגרסה החדשה.');if(!quiet)renderKupaDependentView();return false}const remote=normalizeSharedChecks(row.state?.checks||[]),local=normalizeSharedChecks(state.checks);if(!checksCloudBase&&local.length&&!eq(local,remote)){checksCloudLastError='נמצאו צ\'קים מקומיים ללא גרסת בסיס והם שונים מהענן';markChecksPending();const err=new Error('נמצאו צ\'קים מקומיים שלא ניתן להוכיח שסונכרנו לפני המעבר. הנתונים המקומיים נשמרו ולא נדרסו. יש לבדוק אותם לפני המשך.');if(required)throw err;if(!quiet)toast(err.message);renderKupaDependentView();return false}const base=checksCloudBase?clone(checksCloudBase):clone(local),merged=mergeSharedChecks(base,local,remote);if(merged.conflicts.length){checksCloudLastError='אותו צ\'ק שונה במקביל בשתי המערכות';markChecksPending();const err=new Error('הצ\'קים לא נדרסו: נמצאה עריכה מקבילה של אותו צ\'ק.');if(required)throw err;if(!quiet)toast(err.message);renderKupaDependentView();return false}state.checks=clone(merged.checks);checksBankEvents=normalizeSharedBankEvents(row.state.bankEvents);recomputeKupaNetFromCache();checksCloudBase=clone(remote);persistChecksBase(checksCloudBase,checksBankEvents);checksCloudRevision=Number(row.revision||0);checksCloudLastError='';localSnapshot();try{if(dirHandle)await writeStateToFolder()}catch(e){console.error('checks local mirror',e)}if(!eq(merged.checks,remote)){markChecksPending();queueSharedChecksSave('שינויי הצ\'קים המקומיים מוזגו לענן')}else{clearChecksPending();checksSaveRequested=false}if(!quiet)renderKupaDependentView();return true}catch(e){console.error('shared checks pull',e);checksCloudLastError=e.message||String(e);if(required)throw e;if(!quiet)renderKupaDependentView();return false}finally{checksCloudBusy=false;if(checksSaveRequested)setTimeout(()=>saveSharedChecksToCloud(checksSaveMessage||sharedChecksSaveMessage),0)}}
async function saveSharedChecksToCloud(message='הצ\'קים סונכרנו'){if(!primaryTab)return false;checksSaveRequested=true;checksSaveMessage=message||checksSaveMessage;if(!loadSession()||!navigator.onLine){markChecksPending();return false}if(checksCloudBusy)return checksSavePromise||false;if(checksSavePromise)return checksSavePromise;clearTimeout(sharedChecksSaveTimer);sharedChecksSaveTimer=null;checksSavePromise=(async()=>{let allOk=true;while(checksSaveRequested&&loadSession()&&navigator.onLine){checksSaveRequested=false;const msg=checksSaveMessage||'הצ\'קים סונכרנו';checksSaveMessage='';const startGeneration=checksGeneration,local=normalizeSharedChecks(state.checks),base=checksCloudBase?clone(checksCloudBase):clone(local);checksCloudBusy=true;try{let savedChecks=null,savedRevision=checksCloudRevision;for(let attempt=0;attempt<3;attempt++){const row=await readSharedChecksCloud();if(!row)throw new Error('מאגר הצ\'קים המשותף חסר. אין ליצור אותו אוטומטית; יש להשלים cutover תקין.');const remote=normalizeSharedChecks(row.state?.checks||[]);if(!checksCloudBase&&local.length&&!eq(local,remote)){checksCloudLastError='נמצאו צ\'קים מקומיים ללא גרסת בסיס והם שונים מהענן';markChecksPending();toast('הסנכרון נעצר: נמצאו צ\'קים מקומיים ללא גרסת בסיס והם שונים מהענן. לא נדרס אף שינוי.');renderKupaDependentView();allOk=false;break}const merged=mergeSharedChecks(base,local,remote);if(merged.conflicts.length){checksCloudLastError='אותו צ\'ק שונה במקביל בשתי המערכות';markChecksPending();toast('הסנכרון נעצר: אותו צ\'ק שונה בשתי המערכות. לא נדרס אף שינוי.');renderKupaDependentView();allOk=false;break}const res=await rpcSaveSharedChecks(merged.checks,Number(row.revision||0));if(!res.r.ok){const em=res.j?.message||res.txt||'שמירת הצ\'קים המשותפים נכשלה';if(String(em).includes('revision_conflict'))continue;throw new Error(em)}savedChecks=normalizeSharedChecks(res.row?.state?.checks||merged.checks);checksBankEvents=normalizeSharedBankEvents(res.row?.state?.bankEvents||row.state.bankEvents);savedRevision=Number(res.row?.revision||Number(row.revision||0)+1);break}if(!savedChecks){if(allOk){checksCloudLastError='מסמך הצ\'קים השתנה שוב בזמן הסנכרון';markChecksPending();allOk=false}break}checksCloudBase=clone(savedChecks);persistChecksBase(checksCloudBase,checksBankEvents);checksCloudRevision=savedRevision;checksCloudLastError='';if(checksGeneration===startGeneration){state.checks=clone(savedChecks);recomputeKupaNetFromCache();clearChecksPending()}else{const rebased=mergeSharedChecksPreferLocal(local,normalizeSharedChecks(state.checks),savedChecks);state.checks=clone(rebased.checks);markChecksPending();checksSaveRequested=true}localSnapshot();try{if(dirHandle)await writeStateToFolder()}catch(e){console.error('checks local mirror',e)}renderKupaDependentView();if(!checksSaveRequested&&!checksPendingExists()&&msg)toast(msg)}catch(e){console.error('shared checks save',e);checksCloudLastError=e.message||String(e);markChecksPending();allOk=false;renderKupaDependentView();break}finally{checksCloudBusy=false}}return allOk&&!checksPendingExists()})().finally(()=>{checksSavePromise=null;if(checksSaveRequested&&navigator.onLine&&!checksCloudBusy)setTimeout(()=>saveSharedChecksToCloud(checksSaveMessage||sharedChecksSaveMessage),0)});return checksSavePromise}
async function pollSharedChecks(){if(!primaryTab)return;if(!loadSession()||checksCloudBusy||!navigator.onLine)return;if(checksHaveLocalWork()){await saveSharedChecksToCloud('שינויי הצ\'קים סונכרנו');return}checksCloudBusy=true;try{const meta=await readSharedChecksCloudMeta();if(!meta)return;const rev=Number(meta.revision||0);if(rev>checksCloudRevision){const row=await readSharedChecksCloud();if(!row)return;const fullRev=Number(row.revision||0);if(fullRev<=checksCloudRevision)return;const remote=normalizeSharedChecks(row.state?.checks||[]);state.checks=clone(remote);checksBankEvents=normalizeSharedBankEvents(row.state?.bankEvents);recomputeKupaNetFromCache();checksCloudBase=clone(remote);persistChecksBase(checksCloudBase,checksBankEvents);checksCloudRevision=fullRev;checksCloudLastError='';clearChecksPending();localSnapshot();try{if(dirHandle)await writeStateToFolder()}catch(e){console.error(e)}renderKupaDependentView()}}catch(e){console.error('shared checks poll',e)}finally{checksCloudBusy=false;if(checksSaveRequested)setTimeout(()=>saveSharedChecksToCloud(checksSaveMessage||sharedChecksSaveMessage),0)}}
function mergeSharedChecksPreferLocal(base,local,remote){const conflicts=[];const checks=mergeArray(base||[],local||[],remote||[],'id',conflicts,'check',true);return{checks:normalizeSharedChecks(checks),conflicts}}
async function saveCloudSnapshot(snapshot,startGeneration){let base=lastCloudState?clone(lastCloudState):clone(snapshot),expected=cloudRevision,res=await rpcSave(snapshot,expected),serverSnapshot=clone(snapshot),mergedRemote=false;if(!res.r.ok&&String(res.j?.message||res.txt).includes('revision_conflict')){const remote=await readCloud();if(!remote)throw new Error('מסמך הענן לא נמצא בזמן פתרון התנגשות');const merged=merge3(base,snapshot,remote.state||{});if(merged.conflicts.length){cloudConflictBlocked=true;markCloudPending();setCloud('ענן: התנגשות','error');toast('יש התנגשות בענן באותה רשומה. הנתונים המקומיים נשמרו ולא נדרסו.');return false}serverSnapshot=prepareCloudState(merged.state);expected=Number(remote.revision||0);res=await rpcSave(serverSnapshot,expected);mergedRemote=true}if(!res.r.ok)throw new Error(res.j?.message||res.txt||'שמירה לענן נכשלה');cloudRevision=Number(res.row?.revision||expected+1);lastCloudState=clone(serverSnapshot);localStorage.setItem(CLOUD_BASE_KEY,JSON.stringify(lastCloudState));cloudConflictBlocked=false;if(localGeneration===startGeneration){if(mergedRemote)applyOrderCloudState(serverSnapshot);clearCloudPending()}else{if(mergedRemote){const sharedChecks=clone(state.checks||[]),rebased=merge3(snapshot,prepareCloudState(state),serverSnapshot,{preferLocalConflicts:true});state=normalizeState(rebased.state);state.checks=sharedChecks}localSnapshot();markCloudPending();cloudSaveRequested=true}localSnapshot();try{if(dirHandle)await writeStateToFolder()}catch(localError){console.error('local backup/mirror',localError)}return true}
async function requestCloudSave(message='השינויים סונכרנו'){if(!primaryTab)return false;if(message)cloudSaveMessage=message;cloudSaveRequested=true;if(!cloudEnabled())return false;if(cloudConflictBlocked){setCloud('ענן: התנגשות','error');return false}if(!navigator.onLine){markCloudPending();setCloud('ענן: אופליין','offline');return false}if(cloudSavePromise)return cloudSavePromise;cloudSavePromise=(async()=>{let allOk=true;while(cloudSaveRequested&&cloudEnabled()&&navigator.onLine&&!cloudConflictBlocked){cloudSaveRequested=false;const msg=cloudSaveMessage||'השינויים סונכרנו';cloudSaveMessage='';const startGeneration=localGeneration,snapshot=prepareCloudState();if(!markCloudPending())setSave('מקומי: שגיאת pending','error');cloudBusy=true;setCloud('ענן: מסנכרן…');try{const ok=await saveCloudSnapshot(snapshot,startGeneration);if(!ok){allOk=false;break}if(localGeneration>startGeneration||cloudPendingExists())cloudSaveRequested=true;if(!cloudSaveRequested&&!cloudPendingExists()){setCloud('ענן: מסונכרן','synced');if(msg)toast(msg)}else setCloud('ענן: מסנכרן…')}catch(e){console.error('cloud save',e);markCloudPending();setCloud(navigator.onLine?'ענן: ממתין לסנכרון':'ענן: אופליין',navigator.onLine?'':'offline');allOk=false;break}finally{cloudBusy=false}}return allOk&&!cloudPendingExists()})().finally(()=>{cloudSavePromise=null;if(cloudSaveRequested&&navigator.onLine&&!cloudConflictBlocked)setTimeout(()=>requestCloudSave(cloudSaveMessage||'השינויים סונכרנו'),0)});return cloudSavePromise}
async function saveCloud(msg='השינויים סונכרנו'){return requestCloudSave(msg)}
async function restorePendingAgainstCloud(row){const pendingRaw=loadCloudPendingState()||((cloudSaveRequested||!!(lastCloudState&&!sameOrderCloudData(state,lastCloudState)))?clone(state):null);if(!pendingRaw)return false;const pending=normalizeState(clone(pendingRaw)),remote=normalizeState(clone(row.state||{})),base=lastCloudState?normalizeState(clone(lastCloudState)):null;state=pending;cloudRevision=Number(row.revision||0);if(!base){cloudConflictBlocked=true;setCloud('ענן: נדרש שחזור','error');localSnapshot();toast('נמצאו שינויים מקומיים שלא סונכרנו, אך חסרה גרסת הבסיס. הנתונים המקומיים נשמרו ולא נדרסו.');return true}const merged=merge3(base,pending,remote);if(merged.conflicts.length){cloudConflictBlocked=true;setCloud('ענן: התנגשות','error');localSnapshot();toast('נמצאו שינויים מקומיים ועדכון ענן באותה רשומה. שום נתון לא נדרס.');return true}state=normalizeState(merged.state);lastCloudState=clone(remote);localStorage.setItem(CLOUD_BASE_KEY,JSON.stringify(lastCloudState));localSnapshot();markCloudPending();localGeneration=Math.max(localGeneration,1);cloudSaveRequested=true;await requestCloudSave('שינויים מקומיים שוחזרו וסונכרנו');return true}
async function cloudPoll(){if(!primaryTab)return;if(!cloudEnabled()||cloudBusy||!navigator.onLine)return;if(cloudHasLocalWork()){await requestCloudSave('סונכרנו שינויים מקומיים ועדכון מרחוק');await pollSharedChecks();return}try{cloudBusy=true;const meta=await readCloudMeta();if(!meta)return;if(Number(meta.revision||0)>cloudRevision){const row=await readCloud();if(!row)return;if(Number(row.revision||0)<=cloudRevision)return;applyOrderCloudState(row.state);cloudRevision=Number(row.revision);lastCloudState=prepareCloudState(state);localStorage.setItem(CLOUD_BASE_KEY,JSON.stringify(lastCloudState));clearCloudPending();localSnapshot();try{if(dirHandle)await writeStateToFolder()}catch(localError){console.error('local backup/mirror',localError)}setCloud('ענן: מסונכרן','synced');render();toast('התקבל עדכון מהענן')}}catch(e){console.error(e)}finally{cloudBusy=false;await pollSharedChecks();await refreshKupaReadout()}}
function startPolling(){clearInterval(cloudPollTimer);cloudPollTimer=setInterval(cloudPoll,12000)}
function loginModal(mode='open'){if(!supaConfigured())return alert('הגדרת Supabase חסרה. בדוק supabase/config.js');const email=localStorage.getItem(CLOUD_EMAIL_KEY)||'';modal(mode==='upload'?'הפעלת ענן נפרד לניהול הזמנות':'פתיחת ניהול הזמנות מהענן',`<div class="form-grid"><div class="field full"><div class="notice">ניהול ההזמנות נשמר בטבלאות <b>order_management_*</b>. טאב הצ'קים קורא וכותב ישירות למאגר הצ'קים המשותף <b>shared_checks_documents/main</b>. בנוסף, כרטיס „מאזן קופה נטו” קורא בנפרד את <b>kupa_documents/main</b> לצורך חישוב בלבד; ניהול ההזמנות אינו יוצר מסלול כתיבה חדש לנתוני עו״ש, אשראי, הוצאות או מזומן.</div></div><div class="field full"><label>אימייל Supabase Auth</label><input id="cEmail" type="email" value="${esc(email)}"></div><div class="field full"><label>סיסמה</label><input id="cPassword" type="password"></div></div>`,`<button class="btn primary" onclick="finishCloudLogin('${mode}')">התחבר</button><button class="btn" onclick="closeModal()">ביטול</button>`)}
async function finishCloudLogin(mode){const email=$('#cEmail').value.trim(),pass=$('#cPassword').value;if(!email||!pass)return toast('יש להזין אימייל וסיסמה');try{await authPassword(email,pass);closeModal();if(mode==='upload')await enableCloud(true);else await openCloud()}catch(e){console.error(e);toast('התחברות נכשלה: '+e.message)} }
async function enableCloud(afterLogin=false){if(!primaryTab)return showSecondaryTabGuard();if(!supaConfigured())return alert('הגדרת Supabase חסרה');if(!loadSession()&&!afterLogin)return loginModal('upload');try{setCloud('ענן: בודק…');const existing=await readCloud();localStorage.setItem(CLOUD_AUTO_KEY,'1');if(existing){if(!(await restorePendingAgainstCloud(existing))){cloudConflictBlocked=false;applyOrderCloudState(existing.state);cloudRevision=Number(existing.revision||0);lastCloudState=prepareCloudState(state);localStorage.setItem(CLOUD_BASE_KEY,JSON.stringify(lastCloudState));clearCloudPending();localSnapshot();try{if(dirHandle)await writeStateToFolder()}catch(localError){console.error('local backup/mirror',localError)}setCloud('ענן: מסונכרן','synced');render();toast('כבר היה מסמך ניהול הזמנות בענן — נטענה גרסת הענן ולא נדרסה.')}}else{cloudRevision=0;lastCloudState=clone(prepareCloudState());localStorage.setItem(CLOUD_BASE_KEY,JSON.stringify(lastCloudState));markCloudPending();localGeneration=Math.max(localGeneration,1);await requestCloudSave('נתוני ניהול ההזמנות הועלו לענן הנפרד')}await syncSharedChecksFromCloud({quiet:true,required:true});await refreshKupaReadout({force:true});startPolling()}catch(e){console.error(e);toast('לא ניתן להפעיל ענן: '+e.message);setCloud('ענן: שגיאה','error')}}
async function openCloud({renderAfter=true}={}){if(!primaryTab)return false;if(!loadSession())return loginModal('open');try{setCloud('ענן: פותח…');const row=await readCloud();if(!row){setCloud('ענן: אין מסמך','error');return toast('אין עדיין מסמך ניהול הזמנות בענן. השתמש ב"הפעל ענן והעלה".')};localStorage.setItem(CLOUD_AUTO_KEY,'1');const restored=await restorePendingAgainstCloud(row);if(!restored){cloudConflictBlocked=false;applyOrderCloudState(row.state);cloudRevision=Number(row.revision||0);lastCloudState=prepareCloudState(state);localStorage.setItem(CLOUD_BASE_KEY,JSON.stringify(lastCloudState));clearCloudPending();localSnapshot();try{if(dirHandle)await writeStateToFolder()}catch(localError){console.error('local backup/mirror',localError)}setCloud('ענן: מסונכרן','synced')}await syncSharedChecksFromCloud({quiet:true,required:true});closeModal();if(renderAfter)render();startPolling();if(!cloudConflictBlocked)toast(restored?'ניהול ההזמנות שוחזר וסונכרן':'ניהול ההזמנות נטען מהענן')}catch(e){console.error(e);toast('פתיחת הענן נכשלה: '+e.message);setCloud('ענן: שגיאה','error')}}
function logoutCloud(){saveSession(null);localStorage.removeItem(CLOUD_AUTO_KEY);cloudRevision=0;cloudConflictBlocked=false;cloudSaveRequested=false;clearInterval(cloudPollTimer);setCloud('ענן: לא פעיל');renderSettings();toast('נותקת מהענן; העותק המקומי ונתוני השחזור נשמרו')}

function noteDisplayDate(note){const raw=note?.updatedAt||note?.createdAt;if(!raw)return 'נשמר';const d=new Date(raw);if(Number.isNaN(d.getTime()))return 'נשמר';return 'עודכן '+new Intl.DateTimeFormat('he-IL',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'}).format(d)}
function noteSortRows(){return [...(state.notes||[])].sort((a,b)=>String(b.createdAt||'').localeCompare(String(a.createdAt||'')))}
function resizeStickyNoteTextarea(el){if(!el)return;el.style.height='auto';el.style.height=Math.max(132,el.scrollHeight)+'px'}
function resizeAllStickyNotes(){document.querySelectorAll('.sticky-note textarea').forEach(resizeStickyNoteTextarea)}
function addStickyNote(){const now=new Date().toISOString(),note={id:uid('NOTE'),content:'',createdAt:now,updatedAt:now};state.notes.unshift(note);notesBulkSelected.clear();scheduleSave('פתק חדש נוסף');renderNotes();requestAnimationFrame(()=>{const el=document.querySelector(`[data-note-id="${note.id}"] textarea`);if(el){resizeStickyNoteTextarea(el);el.focus()}})}
function updateStickyNote(id,el){const note=state.notes.find(x=>x.id===id);if(!note)return;note.content=el.value;note.updatedAt=new Date().toISOString();resizeStickyNoteTextarea(el);const date=el.closest('.sticky-note')?.querySelector('[data-note-date]');if(date)date.textContent=noteDisplayDate(note);scheduleSave('הפתק עודכן')}
function deleteStickyNote(id){const note=state.notes.find(x=>x.id===id);if(!note)return;if(!confirm('למחוק את הפתק הזה?'))return;state.notes=state.notes.filter(x=>x.id!==id);notesBulkSelected.delete(id);scheduleSave('הפתק נמחק');renderNotes()}
function toggleNotesBulkMode(){notesBulkMode=!notesBulkMode;notesBulkSelected.clear();renderNotes()}
function toggleNotesBulkRow(id,checked){if(!notesBulkMode||!state.notes.some(x=>x.id===id))return;if(checked)notesBulkSelected.add(id);else notesBulkSelected.delete(id);syncNotesBulkUi()}
function toggleNotesBulkVisible(){if(!notesBulkMode)return;const ids=noteSortRows().map(x=>x.id),all=ids.length>0&&ids.every(id=>notesBulkSelected.has(id));ids.forEach(id=>all?notesBulkSelected.delete(id):notesBulkSelected.add(id));syncNotesBulkUi()}
function notesBulkControls(){return `<div class="notes-bulk-controls"><button class="btn small bulk-select-toggle ${notesBulkMode?'active':''}" onclick="toggleNotesBulkMode()">${notesBulkMode?'סיום בחירה':'בחירה'}</button>${notesBulkMode?`<button id="notesBulkAll" class="btn small bulk-select-all-btn" onclick="toggleNotesBulkVisible()">בחר הכל</button><button id="notesBulkDelete" class="btn danger small bulk-delete-btn" onclick="deleteSelectedStickyNotes()" disabled>מחק נבחרים</button>`:''}</div>`}
function syncNotesBulkUi(){if(!notesBulkMode)return;const valid=new Set(state.notes.map(x=>x.id));[...notesBulkSelected].forEach(id=>{if(!valid.has(id))notesBulkSelected.delete(id)});const del=$('#notesBulkDelete');if(del){del.disabled=!notesBulkSelected.size;del.textContent=notesBulkSelected.size?`מחק ${notesBulkSelected.size}`:'מחק נבחרים'}const ids=noteSortRows().map(x=>x.id),all=ids.length>0&&ids.every(id=>notesBulkSelected.has(id)),allBtn=$('#notesBulkAll');if(allBtn)allBtn.textContent=all?'בטל הכל':'בחר הכל';document.querySelectorAll('[data-note-id]').forEach(card=>{const selected=notesBulkSelected.has(card.dataset.noteId);card.classList.toggle('bulk-selected-card',selected);const cb=card.querySelector('[data-note-bulk-check]');if(cb)cb.checked=selected})}
function deleteSelectedStickyNotes(){const valid=new Set(state.notes.map(x=>x.id)),ids=[...notesBulkSelected].filter(id=>valid.has(id));if(!ids.length)return toast('לא נבחרו פתקים למחיקה');if(!confirm(`למחוק ${ids.length} פתקים שנבחרו?`))return;const set=new Set(ids);state.notes=state.notes.filter(x=>!set.has(x.id));notesBulkSelected.clear();scheduleSave(`${ids.length} פתקים נמחקו`);renderNotes()}
function stickyNoteCard(note){const selected=notesBulkSelected.has(note.id);return `<article class="sticky-note ${selected?'bulk-selected-card':''}" data-note-id="${esc(note.id)}">${notesBulkMode?`<label class="sticky-note-select" title="בחר פתק"><input type="checkbox" data-note-bulk-check ${selected?'checked':''} onchange="toggleNotesBulkRow('${esc(note.id)}',this.checked)"></label>`:''}<div class="sticky-note-paper"><textarea aria-label="תוכן הפתק" placeholder="כתוב כאן הערה או תזכורת…" oninput="updateStickyNote('${esc(note.id)}',this)">${esc(note.content)}</textarea></div><footer class="sticky-note-footer"><span class="sticky-note-date" data-note-date>${esc(noteDisplayDate(note))}</span><button class="btn danger small" onclick="deleteStickyNote('${esc(note.id)}')">מחק</button></footer></article>`}
function renderNotes(){const rows=noteSortRows();$('#main').innerHTML=`<div class="notes-view"><section class="hero notes-hero"><div><h1>הערות</h1><p>פתקים מהירים לתזכורות ומעקב. כל שינוי נשמר יחד עם נתוני המערכת ומסתנכרן לענן כשסנכרון פעיל.</p></div><div class="notes-actions"><button class="btn primary" onclick="addStickyNote()">+ פתק חדש</button>${notesBulkControls()}</div></section><div class="notes-grid">${rows.map(stickyNoteCard).join('')||`<div class="notes-empty"><b>אין עדיין פתקים</b>לחץ על „פתק חדש” כדי לרשום תזכורת ראשונה.</div>`}</div></div>`;mountViewLayout({sourceSelector:'.notes-view',headCount:1,className:'notes-view',scrollKey:'notes'});requestAnimationFrame(()=>{resizeAllStickyNotes();syncNotesBulkUi()})}

function renderSettings(){$('#main').innerHTML=`<section class="hero"><div><h1>הגדרות, ענן וגיבוי</h1><p>נתוני ההזמנות והקופה נשמרים במאגרים נפרדים; רשימת הצ'קים משותפת בין המערכות, ו„מאזן קופה נטו” נקרא מנתוני הקופה בענן לצורך תצוגה וחישוב בלבד.</p></div></section><div class="settings-grid">
<div class="settings-card"><h3>Supabase — מאגר נפרד</h3><div class="notice">ניהול ההזמנות עצמו: <b>order_management_documents</b> ו־<b>order_management_document_backups</b>, דרך <b>save_order_management_document</b>.<br>טאב הצ'קים קורא ומעדכן את <b>shared_checks_documents/main</b> דרך <b>save_shared_checks_document</b>; הצ'קים אינם נשמרים עוד כעותק פעיל במסמך ההזמנות או במסמך הקופה. כרטיס „מאזן קופה נטו” קורא את נתוני הקופה ואת הצ'קים המשותפים לחישוב בלבד ואינו מוסיף כתיבה שלהם מניהול ההזמנות.</div><p>לפני החיבור הראשון יש להריץ פעם אחת את <b>supabase/setup.sql</b> של ניהול ההזמנות. לפני מעבר הייצור יש להריץ את מיגרציית <b>supabase/shared/cutover.sql</b> המצורפת, ורק אחריה להעלות את שתי גרסאות האתר החדשות.</p><div class="settings-row"><button class="btn primary" onclick="enableCloud()">הפעל ענן והעלה</button><button class="btn" onclick="openCloud()">פתח מהענן</button><button class="btn danger" onclick="logoutCloud()">התנתק</button></div><p>סטטוס: ${cloudEnabled()?'פעיל':'לא פעיל'}</p></div>
<div class="settings-card supplier-settings-card"><h3>ניהול ספקים</h3><p>הוספה, עריכה וסידור ספקים מרוכזים כאן כדי להשאיר את כרטיס הספק פנוי לעבודה השוטפת.</p><div class="settings-row"><button class="btn primary" onclick="openSupplierModal()">+ הוספת ספק</button><button class="btn" onclick="openSupplierOrderModal()">סידור ספקים</button></div><div class="supplier-edit-control"><label for="settingsSupplierEdit">בחירת ספק לעריכה</label><div class="supplier-edit-picker"><select id="settingsSupplierEdit" aria-label="בחר ספק לעריכה">${orderedSuppliers().map(sp=>`<option value="${esc(sp.id)}" ${sp.id===currentSupplierId?'selected':''}>${esc(sp.name)}</option>`).join('')}</select><button class="btn" onclick="openSelectedSupplierEditor()">עריכת ספק</button></div></div><p>${state.suppliers.length} ספקים פעילים · הסדר בתפריט הספקים נשמר לפי הסדר שהוגדר ב„סידור ספקים”.</p></div>
<div class="settings-card"><h3>סידור רשימת המחסן</h3><p>קובע את סדר קטגוריות המלאי בתצוגת המחסן. הסדר נשמר גם בענן ובגיבויים; קטגוריות חדשות מצטרפות בלי לשבור את הסדר הקיים.</p><div class="settings-row"><button class="btn" onclick="openInventoryCategoryOrderModal()">סידור קטגוריות במחסן</button></div><p>${orderedInventoryCategoryNames().length} קטגוריות פעילות · “אביזרים” מוגדר כברירת מחדל בסוף הרשימה.</p></div>
<div class="settings-card"><h3>שמירה מקומית וגיבויים</h3><p>כל שינוי נשמר קודם בדפדפן ומגובה גם ב־IndexedDB, והענן פועל בנפרד. תיקיית המחשב היא שכבת גיבוי נוספת בלבד: אם הדפדפן דורש אישור מחדש, העבודה והשמירה בדפדפן ובענן ממשיכות ללא תלות בה. קובץ העבודה נכתב אל <b>data/${DATA_FILE}</b>; גיבוי אוטומטי בתיקיית <b>backups</b> נוצר לכל היותר פעם ב־12 שעות ורק כשהנתונים השתנו.</p><div class="settings-row"><button class="btn" onclick="chooseFolder()">${dirHandle?'החלף תיקייה':'חבר תיקייה'}</button>${dirHandle&&dirPermission!=='granted'?'<button class="btn primary" onclick="activateSavedFolder()">אשר גישה מחדש</button>':''}<button class="btn" onclick="backupToFolder()">גיבוי לתיקייה</button><button class="btn" onclick="exportJson()">ייצא JSON</button><button class="btn" onclick="beginJsonRestore()">שחזר מ־JSON</button><button class="btn" onclick="exportCsv()">ייצא CSV</button></div><p>${dirHandle?`תיקייה זכורה: ${esc(dirHandle.name)} · ${dirPermission==='granted'&&!folderLastError?'גישה פעילה':folderLastError?`שגיאת גיבוי: ${esc(folderLastError)}`:'ממתינה לאישור דפדפן — אין השפעה על שמירת הדפדפן והענן'}`:'לא חוברה תיקייה; השמירה בדפדפן ובענן ממשיכה כרגיל.'}</p></div></div>`;mountViewLayout({headCount:1,className:'settings-view-shell',scrollKey:'settings'})}
function switchView(view){currentView=view;supplierBulkMode=false;supplierMoveTargetId=null;supplierBulkSelected.clear();customerBulkMode=false;customerBulkSelected.clear();serviceBulkMode=false;serviceBulkSelected.clear();warehouseBulkMode=false;warehouseBulkSelected.clear();notesBulkMode=false;notesBulkSelected.clear();if(currentView==='supplier'){if(!currentSupplierId)currentSupplierId=state.suppliers[0]?.id;supplierYearView='current'}searchText='';render()}
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>switchView(b.dataset.view)));
document.addEventListener('click',e=>{const menu=$('#supplierMenu');if(menu&&!menu.contains(e.target))closeSupplierMenu()});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeSupplierMenu()});
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&loadSession())setTimeout(pollSharedChecks,120)});
window.addEventListener('online',()=>{if(cloudEnabled()){setCloud('ענן: חזרה רשת…');setTimeout(()=>{const resume=cloudHasLocalWork()?requestCloudSave('שינויים ממתינים סונכרנו'):Promise.resolve(true);resume.then(()=>cloudPoll())},250)}else if(loadSession())setTimeout(pollSharedChecks,300)});window.addEventListener('offline',()=>{if(cloudEnabled())setCloud('ענן: אופליין','offline')});
window.addEventListener('pagehide',()=>{if(!primaryTab)return;const ok=localSnapshot();if(cloudEnabled()&&ok&&cloudHasLocalWork())markCloudPending();if(loadSession()&&checksHaveLocalWork())markChecksPending()});
(async function boot(){await acquirePrimaryTabLock();try{await requestPersistentBrowserStorage()}catch(e){console.error(e)}try{await restoreBrowserStateFallback()}catch(e){console.error(e)}try{dirHandle=await loadDirHandle();if(dirHandle)await refreshDirPermission(false);else syncFolderAccessButton()}catch(e){console.error(e);syncFolderAccessButton()}if(!primaryTab){setCloud('ענן: לשונית משנית','offline');render({supplierScrollMode:'end'});showSecondaryTabGuard();return}try{lastCloudState=JSON.parse(localStorage.getItem(CLOUD_BASE_KEY)||'null')}catch(e){}const pending=loadCloudPendingState();if(pending){state=normalizeState(clone(pending));localGeneration=Math.max(localGeneration,1);cloudSaveRequested=true}else if(cloudEnabled()&&lastCloudState&&!sameOrderCloudData(state,lastCloudState)){localGeneration=Math.max(localGeneration,1);cloudSaveRequested=true;markCloudPending()}else if(cloudEnabled()&&!lastCloudState&&hasMeaningfulLocalData(state)){localGeneration=Math.max(localGeneration,1);cloudSaveRequested=true;markCloudPending()}if(checksPendingExists()){checksGeneration=Math.max(checksGeneration,1);checksSaveRequested=true}if(cloudEnabled()&&navigator.onLine){try{await openCloud({renderAfter:false})}catch(e){console.error(e);if(folderBackupAvailable())try{await maybeCreateAutomaticFolderBackup(prepareState())}catch(be){console.error(be)}}}else{if(cloudEnabled()&&!navigator.onLine)setCloud('ענן: אופליין','offline');if(loadSession()&&navigator.onLine)try{await syncSharedChecksFromCloud({quiet:true,required:true});await refreshKupaReadout({force:true})}catch(e){console.error(e)}if(folderBackupAvailable())try{await maybeCreateAutomaticFolderBackup(prepareState())}catch(e){console.error(e)}}render({supplierScrollMode:'end'});syncFolderAccessButton();setSave('מקומי: שמור','',folderSaveTitle());})();

if('serviceWorker' in navigator){window.addEventListener('load',()=>navigator.serviceWorker.register('./service-worker.js').catch(console.error));}
